ize:10px;font-weight:500}.activity-item small{display:block;color:#76786e;font-size:9px;margin-top:4px}.provider-card{margin-top:14px;border:1px solid #272920;background:#151610;border-radius:8px;padding:12px}.provider-head{display:flex;align-items:center;gap:8px}.provider-badge{width:24px;height:24px;background:#202117;border:1px solid #383a2d;color:var(--yellow);display:grid;place-items:center;border-radius:6px}.provider-head b{font-size:10px}.provider-head small{display:block;font-size:9px;color:#7d7f75;margin-top:3px}.provider-status{margin-left:auto;color:#b6d473;font:9px var(--mono)}.provider-card p{font-size:9px;color:#898b81;line-height:1.55;margin:10px 0 0}.ai-not-connected{color:#dcbd68}.search-wrap{position:relative}.search-box{border:1px solid #2e3027;background:#11120f;border-radius:7px;color:var(--text);padding:10px 12px 10px 34px;width:235px;outline:none;font-size:11px}.search-box:focus,.field:focus,.select:focus,.textarea:focus{border-color:#9aa34d;box-shadow:0 0 0 3px #eaff680d}.search-glyph{position:absolute;top:9px;left:11px;color:#797b71}.page-heading{display:flex;justify-content:space-between;align-items:end;margin:5px 0 21px}.page-heading h1{font:500 29px var(--display);letter-spacing:-1px;margin:7px 0 5px}.page-heading p{margin:0;color:#909187;font-size:12px}.filter-row{display:flex;align-items:center;gap:7px;margin-bottom:14px;flex-wrap:wrap}.filter-chip{background:#13140f;border:1px solid #2a2b24;border-radius:20px;padding:7px 11px;color:#92948a;font-size:10px}.filter-chip.active,.filter-chip:hover{color:var(--yellow);border-color:#646a37;background:#eaff680a}.all-tools-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:11px}.all-tools-grid .tool-card{min-height:132px;padding:15px}.all-tools-grid .tool-name{font-size:13px;margin-top:16px}.all-tools-grid .tool-desc{font-size:10px}.featured-tool{border-color:#5a602f;background:linear-gradient(140deg,#191b12,#12130f)}.create-grid{display:grid;grid-template-columns:repeat(3,1fr)