function bindSettings(){document.querySelectorAll('[data-settings-tab]').forEach(b=>b.onclick=()=>{settingsTab=b.dataset.settingsTab;render()});const save=document.querySelector('#save-provider');if(save)save.onclick=()=>{config.endpoint=document.querySelector('#setting-endpoint').value.trim().replace(/\/$/,'');config.model=document.querySelector('#setting-model').value.trim();const key=document.querySelector('#setting-key').value.trim();if(key)config.key=key;config.imageModel=document.querySelector('#setting-image-model').value.trim()||'gpt-image-1';localStorage.setItem('karma-settings',JSON.stringify({endpoint:config.endpoint,model:config.model,imageModel:config.imageModel}));toast('Provider settings saved for this tab.');render()};const test=document.querySelector('#test-provider');if(test)test.onclick=async()=>{const endpoint=document.querySelector('#setting-endpoint').value.trim().replace(/\/$/,'');const model=document.querySelector('#setting-model').value.trim();const key=document.querySelector('#setting-key').value.trim()||config.key;if(!endpoint||!model||!key)return toast('Add a base URL, model, and API key first.');test.disabled=true;test.textContent='Testing…';try{const r=await fetch(endpoint+'/chat/completions',{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+key},body:JSON.stringify({model,messages:[{role:'user',content:'Reply with the single word READY.'}],max_tokens:10})});if(!r.ok)throw new Error(`Provider returned ${r.status}`);toast('Connection successful.');}catch(e){toast('Connection failed: '+e.message)}finally{test.disabled=false;test.textContent='Test connection'}};const clear=document.querySelector('#clear-provider');if(clear)clear.onclick=()=>{config={endpoint:'',model:'',key:'',imageModel:'gpt-image-1'};localStorage.removeItem('karma-settings');toast('Provider disconnected.');render()};const reset=document.querySelector('#reset-workspace');if(reset)reset.onclick=()=>{if(confirm('Reset local workspace preferences?')){localStorage.removeItem('karma-settings');config={endpoint:'',model:'',key:'',imageModel:'gpt-image-1'};toast('Workspace preferences reset.');render()}};const motion=document.querySelector('#reduce-motion');if(motion){motion.classList.toggle('on',localStorage.getItem('karma-motion')==='1');motion.onclick=()=>{const val=localStorage.getItem('karma-motion')==='1'?'0':'1';localStorage.setItem('karma-motion',val);document.body.classList.toggle('reduce-motion',val==='1');motion.classList.toggle('on',val==='1')}}}
