rs here</b><p>${id==='image'?'Image generation uses your configured image model.':'Run the tool to get started. AI-generated answers are never fabricated or simulated.'}</p></div></div></section></div>${id==='image'?'<div class="locked-banner"><span class="accent">ⓘ</span><span>Image generation requires a provider that supports the OpenAI-compatible <code>/images/generations</code> endpoint and browser CORS.</span></div>':''}`}
function selectOptions(label){const map={'Language':['JavaScript','Python','TypeScript','HTML + CSS','Other'],'Framework':['Vanilla','React','Vue','Svelte','Other'],'Style':['Photorealistic','Illustration','3D render','Editorial','Minimal'],'Aspect ratio':['Square 1:1','Landscape 16:9','Portrait 9:16'],'Enhancement style':['Detailed and precise','Creative','Concise'],'Analysis focus':['Key themes and tone','Summary','Sentiment','Structure'],'Target language':['Spanish','French','German','Japanese','Chinese','Arabic','Portuguese','English','Other'],'Tone':['Natural','Professional','Friendly','Persuasive','Playful'],'Writing task':['Draft','Rewrite','Proofread','Summarize'],'Number of ideas':['5','8','12'],'Perspective':['Unexpected angles','Practical','Bold','Audience-first'],'Site type':['Landing page','Portfolio','Store','Blog','Dashboard'],'Tech stack':['HTML + CSS','React','Next.js','Vue'],'Detail level':['Step-by-step','Concise','Thorough'],'Platform':['Web','Mobile','Desktop','Tabletop'],'Genre':['Puzzle','Adventure','Strategy','Arcade','Cozy'],'Planning horizon':['Today','This week','This month'],'Format':['Prioritized checklist','Time blocks','Milestones'],'Research depth':['Overview','Detailed','Academic overview'],'Output format':['Structured brief','Bullet summary','Question list']};return map[label]||[label]}
function bindTool(id){const t=tools.find(x=>x.id===id);if(!t)return;const run=document.querySelector('#run-tool');run.onclick=()=>runTool(id);document.querySelector('#copy-result').onclick=async()=>{if(!currentResult)return toast('Nothing to copy yet.');try{await navigator.clipboard.writeText(currentResult);toast('Output copied.')}catch{toast('Clipboard access unavailable.')}};document.querySelector('#download-result').onclick=()=>{if(!currentResult)return toast('Nothing to save yet.');const blob=new Blob([currentResult],{type:'text/plain'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`karma-${id}-output.txt`;a.click();URL.revokeObjectURL(a.href);toast('Output saved.')};if(id==='productivity')bindFocus()}
