function localAnalyze(input){const words=input.trim()?input.trim().split(/\s+/).length:0;const sentences=(input.match(/[.!?]+(?=\s|$)/g)||[]).length|| (words?1:0);const paragraphs=input.trim()?input.trim().split(/\n\s*\n/).length:0;const chars=input.length;const mins=Math.max(1,Math.ceil(words/220));return `LOCAL TEXT STATS\n\nWords: ${words}\nCharacters: ${chars}\nSentences (estimated): ${sentences}\nParagraphs: ${paragraphs}\nEstimated reading time: ${mins} min\n\nThis is a simple browser-based count, not an AI interpretation. Connect an AI provider and use Analyze text for themes, tone, and a written summary.`}
async function runTool(id){const t=tools.find(x=>x.id===id);const input=document.querySelector('#tool-input')?.value.trim();if(!input)return toast('Add a brief to get started.');const run=document.querySelector('#run-tool');const output=document.querySelector('#result-body');run.disabled=true;run.innerHTML='<span class="loading-dots">WORKING…</span>';output.innerHTML='<div class="result-placeholder"><span class="placeholder-icon loading-dots">✳</span><b>Working on it</b><p>Sending only to your configured provider.</p></div>';lastTool=t;
 try{if(id==='analyzer'){setOutput(localAnalyze(input));return}if(id==='productivity'&&!config.endpoint){const plan=`LOCAL FOCUS PLAN\n\nGoal: ${input}\n\n1. Define one small, finishable next action.\n2. Set a 25-minute focus block using the timer.\n3. Put unrelated tasks aside until the block ends.\n4. Take a 5-minute break, then review progress.\n\nThis is a simple local template, not an AI-generated plan. Connect a provider for a tailored plan.`;setOutput(plan);return}if(id==='image'){await runImage(input);return}if(!config.endpoint||!config.model||!config.key){document.querySelector('#result-body').innerHTML=`<div class="result-placeholder"><span class="placeholder-icon">⚙</span><b>Connect an AI provider first</b><p>This tool does not invent an answer. Add a compatible endpoint, model, and key in Settings to get a real response.</p><button class="btn btn-small" data-go="SETTINGS">Open AI settings ↗</button></div>`;document.querySelector('#result-body [data-go]').onclick=()=>setPage('SETTINGS');return}const selects=[...document.querySelectorAll('.tool-form select')].map(e=>e.value);const instructions=`You are an assistant inside KARMA OS. Perform the user's requested ${t.name} task. Be useful, clear, and honest. Do not claim external research or execution you did not perform. Use the user's settings where relevant: ${t.settings.map((s,i)=>s+': '+selects[i]).join('; ')}. Return the result directly.`;const response=await fetch(config.endpoint+'/chat/completions',{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+config.key},body:JSON.stringify({model:config.model,messages:[{role:'system',content:instructions},{role:'user',content:input}]})});if(!response.ok)throw new Error(`Provider returned HTTP ${response.status}`);const data=await response.json();const text=data.choices?.[0]?.message?.content;if(!text)throw new Error('Provider response did not contain text.');setOutput(text);}
 catch(e){setOutput(`REQUEST FAILED\n\n${e.message}\n\nCheck your provider URL, credentials, model name, and CORS settings.`,true)}finally{run.disabled=false;run.innerHTML=`${t.action} <span>↗</span>`}}
