// Create missing initialization/state bindings required by the generated UI.
if (typeof page === 'undefined') var page = 'HOME';
if (typeof restrictedUnlocked === 'undefined') var restrictedUnlocked = false;
if (typeof activeTool === 'undefined') var activeTool = '';
if (typeof searchQuery === 'undefined') var searchQuery = '';
if (typeof category === 'undefined') var category = 'All';
if (typeof settingsTab === 'undefined') var settingsTab = 'AI Provider';

const view = document.querySelector('#view');

function setPage(next) {
  page = next;
  render();
}

function navInit() {
  document.querySelectorAll('[data-nav]').forEach(button => {
    button.onclick = () => setPage(button.dataset.nav);
  });

  const restricted = document.querySelector('#restricted-trigger');
  if (restricted) restricted.onclick = openSecurity;

  const notifications = document.querySelector('#notifications');
  if (notifications) notifications.onclick = () => toast('You are all caught up.');

  const profile = document.querySelector('#profile-menu');
  if (profile) profile.onclick = () => showSettings('Workspace');
}

function bindCards() {
  document.querySelectorAll('[data-tool]').forEach(card => {
    card.onclick = () => {
      activeTool = card.dataset.tool;
      setPage('TOOLS');
    };
  });
}

navInit();
render();
if (localStorage.getItem('karma-motion') === '1') document.body.classList.add('reduce-motion');

